class SafeImageFolder(datasets.ImageFolder):
    def __getitem__(self, index):
        max_attempts = min(100, len(self.samples))
        attempts = 0

        while attempts < max_attempts:
            try:
                path, target = self.samples[index]
                sample = self.loader(path)
                if self.transform is not None:
                    sample = self.transform(sample)
                if self.target_transform is not None:
                    target = self.target_transform(target)
                return sample, target
            except Exception as e:
                index = (index + 1) % len(self.samples)
                attempts += 1

        raise RuntimeError(f"Could not load a valid image after {max_attempts} attempts")

    def __getitems__(self, indices):
        # Override to handle batch loading with error handling
        results = []
        for idx in indices:
            try:
                results.append(self[idx])
            except Exception as e:
                # Skip corrupted images
                continue
        # If we don't have enough samples, try to get more
        while len(results) < len(indices):
            idx = torch.randint(0, len(self.samples), (1,)).item()
            try:
                results.append(self[idx])
            except:
                continue
        return results

train_dataset = SafeImageFolder(root='data_small/eyes data', transform=train_transform)
